import type { MetadataRoute } from 'next';

/**
 * Web app manifest — drives "Install app" on Android/Chrome and the
 * app-icon/home-screen metadata on iOS. Icons are generated by
 * scripts/generate-icons.mjs; the maskable variant keeps the mark inside
 * Android's safe circle.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    id: '/',
    name: 'MELO — Find Your Vibe | African Music & AI Discovery',
    short_name: 'MELO',
    description:
      'An African-first music streaming and discovery platform that uses vibe-based discovery, personalization, and AI to help listeners find music they love — affordably and reliably.',
    start_url: '/',
    scope: '/',
    display: 'standalone',
    orientation: 'portrait',
    background_color: '#121212',
    theme_color: '#121212',
    categories: ['music', 'entertainment'],
    icons: [
      {
        src: '/icons/icon-192x192.png',
        sizes: '192x192',
        type: 'image/png',
        purpose: 'any',
      },
      {
        src: '/icons/icon-512x512.png',
        sizes: '512x512',
        type: 'image/png',
        purpose: 'any',
      },
      {
        src: '/icons/icon-maskable-512x512.png',
        sizes: '512x512',
        type: 'image/png',
        purpose: 'maskable',
      },
    ],
  };
}
